const {
    assigned,
    query,
    api
} = options;

const itemKey = api.exclusionItemKey || 'Id';
const initialAssignedSnapshot = this.helpers._processInitialAssignedSnapshot({
    assigned,
    itemKey
});

let params = [...api.baseParams];

if (query && api.searchParamKey) params.push(`${api.searchParamKey}=${query}`);

if (api.exclusionQueryKey) {
    const liveAssignedIds = assigned.items.map(item => item[itemKey]).filter(id => id);
    const dynamicExclusions = liveAssignedIds.filter(id => initialAssignedSnapshot.includes(id));
    const totalExclusions = [...dynamicExclusions, ...(api.staticExclusions || [])];

    if (totalExclusions.length > 0) {
        params.push(`${api.exclusionQueryKey}=${totalExclusions.join(",")}`);
    }
}

return params.join("&");

const {
    assigned,
    api,
    currentPage = 1
} = options;

const itemKey = api.exclusionItemKey || 'Id';
const initialAssignedSnapshot = this.helpers._processInitialAssignedSnapshot({
    assigned,
    itemKey
});

const limit = 25;
const baseOffset = (currentPage - 1) * limit;

const liveAssignedIds = assigned.items.map(item => item[itemKey]).filter(id => id);
const newAssignmentsCount = liveAssignedIds.filter(id => !initialAssignedSnapshot.includes(id)).length;

// Slide the offset backward by the number of missing items to prevent overshooting
const adjustedOffset = Math.max(0, baseOffset - newAssignmentsCount);

return adjustedOffset;

const {
    assigned,
    itemKey = "Id"
} = options;

return assigned.items.map(item => item[itemKey]).filter(id => id);

