const {
    title,
    assigned,     // { columns: [], items: [] }
    unassigned,   // { columns: [], items: [], totalPages: 1 }
    api,          // { entity: "", baseParams: [], searchParamKey: "", searchProperty: "" }
    mapEntityFn,
    onApply
} = config;

return this.$modal.open("assignment-modal", {
    resolve: {
        title: title,
        assigned: assigned,
        unassigned: {
            columns: unassigned.columns,
            items: unassigned.items,
            pagination: {
                totalPages: unassigned.totalPages,
                fn: async (currentPage, query, assigned) => {
                    try {
                        const res = await this.payrollApiService.get({
                            entity: api.entity,
                            page: currentPage,
                            offset: this.helpers._calculateElasticOffset({
                                assigned,
                                api,
                                currentPage
                            }),
                            query: this.helpers._buildAssignmentQueryString({
                                assigned,
                                query,
                                api
                            }) // Re-evaluates live state
                        });
                        const entities = res.entities ?? res ?? [];
                        return {
                            entities: entities.map(mapEntityFn),
                            metadata: { 
                                currentPage: res.metadata?.currentPage || 1,
                                pageCount: res.metadata?.pageCount || 1
                            }
                        };
                    } catch (err) {
                        console.error(`Pagination failed:`, err);
                        return { entities: [], metadata: { pageCount: unassigned.totalPages } };
                    }
                }
            }
        },
        search: {
            property: api.searchProperty || "Name",
            operation: "contains",
            placeholder: api.searchPlaceholder || `Search by: contains ${api.searchProperty}`,
            fn: async (query, assigned) => {
                try {
                    const res = await this.payrollApiService.get({
                        entity: api.entity,
                        query: this.helpers._buildAssignmentQueryString({
                            assigned,
                            query,
                            api
                        }) // Re-evaluates live state
                    });
                    const entities = res.entities ?? res ?? [];
                    return {
                        entities: entities.map(mapEntityFn),
                        metadata: { pageCount: res.metadata?.pageCount ?? 1 }
                    };
                } catch (err) {
                    console.error("Search failed:", err);
                    return { entities: [], metadata: { pageCount: 1 } };
                }
            }
        }
    }
}).then(res => {
    if (res.applied && typeof onApply === "function") {
        onApply(res.resolve?.assignedItems);
    }
});
